'use strict';
const $ = s => document.querySelector(s);
const esc = x => String(x ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names = {normal:'Regular',holo:'Holo',reverse:'Reverse holo',firstEdition:'First edition',wPromo:'W promo',unspecified:'Unspecified print'};
const anniversaryLogo = 'data:image/png;base64,';
const logoOverrides = {"xy3": "data:image/png;base64,"};
const logoParents = {"mep": "me01", "mee": "me01", "svp": "sv01", "sve": "sv01", "swsh12.5gg": "swsh12.5", "swsh12tg": "swsh12", "swsh11tg": "swsh11", "swsh10tg": "swsh10", "swsh9tg": "swsh9", "cel25cc": "cel25", "swsh4.5sv": "swsh4.5", "sma": "sm115", "rc": "bw11", "xya": "xy1"};
function fallbackLogo(s){const label=s.name.includes("McDonald")?"McDonald's":s.name.includes('trainer Kit')?'TRAINER KIT':s.pokemon?'POKÉMON':s.name;const sub=s.pokemon?s.pokemon.join(' + '):s.id.toUpperCase();return 'data:image/svg+xml,'+encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="240" height="110" viewBox="0 0 240 110"><rect x="2" y="2" width="236" height="106" rx="16" fill="#20283b" stroke="#aa66ee" stroke-width="3"/><text x="120" y="47" text-anchor="middle" fill="#f4eaff" font-family="Arial" font-weight="bold" font-size="${label.length>19?13:19}">${esc(label)}</text><text x="120" y="78" text-anchor="middle" fill="#61dcea" font-family="Arial" font-size="13">${esc(sub)}</text></svg>`);}
function pokemonArt(s){
 if(!s.pokemon)return '';
 return `<div class="pokemon-portraits">${s.pokemon.map(name=>{const c=s.cards.find(c=>c.name.toLowerCase()===name.toLowerCase())||s.cards.find(c=>c.name.toLowerCase().includes(name.toLowerCase()));const dex=c?.dexId?.[0];return dex?`<figure><img src="https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/${Number(dex)}.png" alt="${esc(name)}" data-pokemon-art data-card-fallback="${esc(c.image?c.image+'/low.webp':'')}" loading="lazy"><figcaption>${esc(name)}</figcaption></figure>`:c?.image?`<figure><img src="${esc(c.image)}/low.webp" alt="${esc(name)}" data-pokemon-art><figcaption>${esc(name)}</figcaption></figure>`:'';}).join('')}</div>`;
}
document.addEventListener('error',e=>{const img=e.target;if(!img.hasAttribute?.('data-pokemon-art'))return;if(img.dataset.cardFallback){img.src=img.dataset.cardFallback;delete img.dataset.cardFallback;}},true);
function setLogo(s){if(s.id==='30th'||s.id==='30th-c')return anniversaryLogo;if(logoOverrides[s.id])return logoOverrides[s.id];const parent=logoParents[s.id]|| (s.id.startsWith('tk-xy-')?'xy1':s.id.startsWith('tk-sm-')?'sm1':null);const p=parent&&catalogue.find(x=>x.id===parent);return s.logo?s.logo+'.webp':p?.logo?p.logo+'.webp':fallbackLogo(s);}
document.addEventListener('error',e=>{const img=e.target;if(img.tagName!=='IMG'||img.hasAttribute('data-pokemon-art')||img.dataset.image==='card'||!img.closest('.set-choice,.set-hero,.master-tile'))return;const wrap=img.closest('[data-set]');const id=wrap?.dataset.set;const s=catalogue.find(x=>x.id===id)||{id:'SET',name:'Pokémon TCG'};if(!img.dataset.fallback){img.dataset.fallback='1';img.src=fallbackLogo(s);}},true);

const setNote = s => s.pokemon ? 'English catalogue matches for '+s.pokemon.join(' + ')+'. Includes named forms. Special stamps and unlisted releases may be absent.' : s.id==='30th-c' ? 'Classic reprint subset · tracked separately from the main set' : s.id==='30th' ? 'Main set · Classic Collection tracked separately' : '';
const titles = {browse:['Your next complete set.','Discover the cards. Fill the gaps. Build something worth keeping.','Browse cards'],collection:['A collection that’s yours.','Every pull, every trade, every favourite. All in one place.','My collection'],master:['One card closer.','Turn a whole set into a checklist. See exactly what’s left to find.','Master sets'],wishlist:['The ones you’re chasing.','Keep your next great finds together.','Wishlist'],stats:['Your collection, at a glance.','A little perspective on everything you’ve collected.','Collection stats']};
let S={owned:{},tracked:{},wishlist:[]}, token='', catalogue=[], activeSet=null, view='browse', filter='all', query='', sort='number', pageSize=36, selected=new Set(), cards=new Map(), sets=new Map(), requestId=0, toastTimer;
const modal=$('#modal');
async function api(path,body){const r=await fetch('/api/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json','X-Vault-Token':token}:{},body:body?JSON.stringify({...body,revision:S.revision}):undefined});const d=await r.json();if(!r.ok)throw Error(d.error||'Something went wrong');return d;}
function notify(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4500);}
async function save(action,body){const n=await api(action,body);S=n;summary();return n;}
function variants(c){return Object.keys(names).filter(v=>c.variants?.[v]) .filter(v=>v!=='unspecified').length?Object.keys(names).filter(v=>c.variants?.[v]):['unspecified'];}
function holdings(id){return Object.values(S.owned).filter(x=>x.id===id);}
function qty(id,v){return holdings(id).filter(x=>!v||x.variant===v).reduce((n,x)=>n+x.quantity,0);}
function progress(set,mode){let total=0,have=0;for(const c of set.cards){if(mode==='variants'){for(const v of variants(c)){total++;if(qty(c.id,v))have++;}}else{total++;if(qty(c.id))have++;}}return {total,have,missing:total-have,percent:total?Math.round(have/total*100):0};}
function missing(c){return (view==='browse'?S.tracked[activeSet.id]:S.tracked[c.set.id])?.mode==='variants'?variants(c).some(v=>!qty(c.id,v)):!qty(c.id);}
function money(n){return new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n);}
function price(c,v){const p=c.pricing?.tcgplayer;const key={normal:'normal',holo:'holofoil',reverse:'reverse-holofoil',firstEdition:'1st-edition-normal'}[v];return key&&Number.isFinite(p?.[key]?.marketPrice)?p[key].marketPrice:null;}
function summary(){const entries=Object.values(S.owned),total=entries.reduce((n,x)=>n+x.quantity,0),unique=new Set(entries.map(x=>x.id)).size;$('#summary').innerHTML=`<div class="metric"><small>CARDS IN YOUR VAULT</small><strong>${total.toLocaleString()}</strong><em>${unique} unique cards</em></div><div class="metric"><small>SETS YOU’RE MASTERING</small><strong class="lime">${Object.keys(S.tracked).length}</strong><em>A checklist for every chase</em></div><div class="metric"><small>ON YOUR WISHLIST</small><strong>${S.wishlist.length}</strong><em>Keep your favourites in sight</em></div><div class="metric"><small>EXTRA COPIES</small><strong>${Math.max(0,total-unique)}</strong><em>Includes alternate prints</em></div>`;$('#nav-count').textContent=total;$('#undo').disabled=!S.canUndo;}
function header(){const t=titles[view];$('#page-title').textContent=t[0];$('#page-subtitle').textContent=t[1];$('#crumb').textContent=t[2];document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===view));summary();}
function empty(title,text,action='Explore sets'){return `<div class="empty"><div class="empty-icon">▧</div><h2>${esc(title)}</h2><p>${esc(text)}</p><button class="primary" data-action="explore">${esc(action)}</button></div>`;}
function loading(text='Opening your card catalogue…'){$('#content').innerHTML=`<div class="loading">${esc(text)}</div>`;}
function failure(e){$('#content').innerHTML=`<div class="error">${esc(e.message)}</div><button data-action="retry">Try again</button>`;}
async function getSet(id){if(sets.has(id))return sets.get(id);const data=await api('set/'+encodeURIComponent(id));sets.set(id,data);data.cards.forEach(c=>cards.set(c.id,c));return data;}
async function getCard(id){if(cards.has(id))return cards.get(id);const c=await api('card/'+encodeURIComponent(id));cards.set(id,c);return c;}
async function navigate(next,sid){const rid=++requestId;view=next;query='';filter='all';pageSize=36;selected.clear();selection();header();loading();try{if(view==='browse'){activeSet=await getSet(sid||activeSet?.id||'sv03.5');}else if(view==='master'){await Promise.all(Object.keys(S.tracked).map(getSet));}else if(view==='collection'||view==='wishlist'||view==='stats'){const ids=view==='wishlist'?S.wishlist:[...new Set(Object.values(S.owned).map(x=>x.id))];await Promise.all(ids.map(getCard));}if(rid===requestId)render();}catch(e){if(rid===requestId)failure(e);}}
function render(){header();if(view==='master')renderMasters();else if(view==='stats')renderStats();else renderCards();selection();}
function rarityBadge(c){
 const r=(c.rarity||'').toLowerCase().trim();
 const modern=/^(sv|me|30th)/.test(c.set?.id||'');
 let count=0,tone='ink',shape='star';
 if(r==='common'){count=1;shape='circle';}
 else if(r==='uncommon'){count=1;shape='diamond';}
 else if(r==='rare'||r==='rare holo'){count=1;}
 else if(modern){const m={'double rare':[2,'ink'],'ultra rare':[2,'silver'],'illustration rare':[1,'gold'],'special illustration rare':[2,'gold'],'hyper rare':[3,'gold']};if(m[r]) [count,tone]=m[r];}
 if(!count)return '';
 const shapes={star:'<path d="m12 1.8 3.1 6.3 7 .9-5 4.9 1.2 7-6.3-3.3-6.3 3.3 1.2-7-5-4.9 7-.9z"/>',circle:'<circle cx="12" cy="12" r="8"/>',diamond:'<path d="m12 2 10 10-10 10L2 12z"/>'};
 const label=count+' '+tone+' '+(shape==='star'?'star'+(count===1?'':'s'):shape);
 return `<span class="rarity-symbols ${tone}" role="img" aria-label="${esc(c.rarity)}: ${label}" title="${esc(c.rarity)}">${Array.from({length:count},()=>`<svg viewBox="0 0 24 24" aria-hidden="true">${shapes[shape]}</svg>`).join('')}</span>`;
}
function image(c,cls='card-art',load='lazy'){return c.image?`<img class="${cls}" src="${esc(c.image)}/low.webp" alt="${esc(c.name)}" loading="${load}" data-image="card">`:`<div class="image-placeholder">${esc(c.name)}<small>Artwork not yet available</small></div>`;}
function renderCards(){let all;if(view==='browse')all=activeSet.cards;else if(view==='wishlist')all=S.wishlist.map(id=>cards.get(id)).filter(Boolean);else all=[...new Set(Object.values(S.owned).map(x=>x.id))].map(id=>cards.get(id)).filter(Boolean);
if(!all.length){$('#content').innerHTML=empty(view==='wishlist'?'Make room for your favourites.':'Your vault starts with one card.',view==='wishlist'?'Tap the heart on any card to keep it here.':'Browse a set, select the cards you own and add them together.');return;}
let hero='';if(view==='browse'){const s=activeSet,t=S.tracked[s.id],p=progress(s,t?.mode||'unique');hero=`<div class="set-hero"><div class="set-info">${s.pokemon?pokemonArt(s):setLogo(s)?`<img class="set-logo" src="${esc(setLogo(s))}" alt="${esc(s.name)} logo">`:''}<div><div class="kicker">${esc(s.serie?.name||'POKÉMON TCG')} · ENGLISH</div><h2>${esc(s.name)}</h2><p>${s.cards.length} cards · ${s.pokemon?'Across '+new Set(s.cards.map(c=>c.set.id)).size+' sets':esc(s.releaseDate||'Release date unavailable')}</p>${setNote(s)?`<small class="set-description">${setNote(s)}</small>`:''}</div></div><div class="hero-actions">${t?`<small><b>${p.have} / ${p.total}</b> ${t.mode==='variants'?'prints':'cards'} owned · ${p.percent}%</small><div class="progress"><i style="width:${p.percent}%"></i></div><button data-action="track">✓ Tracking set · Edit scope</button>`:`<button class="primary" data-action="track">＋ Track this whole set</button><div><small>A checklist, ready to fill.</small></div>`}</div></div>${t?`<p class="scope-note">${t.mode==='variants'?'Standard prints checklist: regular, holo, reverse holo and other variants flagged by the catalogue. Stamped, special foil and promotional exceptions are not exhaustive.':'One of each numbered card, including secret cards listed in this set. Any owned print counts.'} ${p.missing} still missing.</p>`:''}`;}
$('#content').innerHTML=hero+`<div class="tools"><input type="search" id="card-search" placeholder="Search cards by name or number…" aria-label="Search cards" value="${esc(query)}"><div class="tabs" aria-label="Card filters">${['all','owned',...(view==='browse'?['missing']:[]),'duplicates'].map(f=>`<button data-filter="${f}" class="${filter===f?'active':''}" aria-pressed="${filter===f}">${{all:'All cards',owned:'Owned',missing:'Missing',duplicates:'Duplicates'}[f]}</button>`).join('')}</div><select id="card-sort" aria-label="Sort cards"><option value="number">Card number</option><option value="name">Name A–Z</option><option value="rarity">Rarity</option></select></div><div class="results-line"><span id="result-count"></span><div>${view==='browse'?'<button data-action="export-missing">↓ Missing list</button> ':''}<button data-action="select-visible">Select displayed cards</button></div></div><div id="card-grid" class="card-grid"></div><div class="load-more" id="load-more"></div>`;$('#card-sort').value=sort;$('#card-search').addEventListener('input',e=>{query=e.target.value;pageSize=36;drawGrid(all);});$('#card-sort').addEventListener('change',e=>{sort=e.target.value;drawGrid(all);});drawGrid(all);}
let displayed=[];
function drawGrid(all){let found=all.filter(c=>(c.name+' '+c.localId).toLowerCase().includes(query.toLowerCase())).filter(c=>filter==='all'||filter==='owned'&&qty(c.id)>0||filter==='missing'&&missing(c)||filter==='duplicates'&&qty(c.id)>1);found.sort((a,b)=>sort==='name'?a.name.localeCompare(b.name):sort==='rarity'?(a.rarity||'').localeCompare(b.rarity||''):a.localId.localeCompare(b.localId,undefined,{numeric:true}));displayed=found.slice(0,pageSize);$('#result-count').textContent=`${found.length} cards${query?' matching your search':''} · ${displayed.length} displayed`;$('#card-grid').innerHTML=displayed.map(c=>{const n=qty(c.id),p=price(c,variants(c)[0]);return `<article class="card ${selected.has(c.id)?'selected':''}" data-card="${esc(c.id)}"><div class="card-top"><label><input type="checkbox" data-select="${esc(c.id)}" aria-label="Select ${esc(c.name)} ${esc(c.localId)}" ${selected.has(c.id)?'checked':''}>#${esc(c.localId)}</label><span class="status-pill ${n?'owned':''}">${n?'✓ '+n+' owned':'Not owned'}</span></div><div data-detail="${esc(c.id)}">${image(c,'card-art'+(n?'':' missing'))}</div><div class="card-text"><button class="card-title" data-detail="${esc(c.id)}">${esc(c.name)}</button><div class="card-meta">${rarityBadge(c)}<span>${esc(c.rarity||'Rarity unavailable')} · ${esc(c.set.name)}</span></div>${(view==='browse'?S.tracked[activeSet.id]:S.tracked[c.set.id])?.mode==='variants'?`<div class="variant-status">${variants(c).map(v=>`<span class="${qty(c.id,v)?'have':'need'}">${qty(c.id,v)?'✓':'○'} ${names[v]}</span>`).join('')}</div>`:''}<div class="card-bottom"><small>${p===null?'Price unavailable':money(p)+' USD'}</small><button data-wish="${esc(c.id)}" class="${S.wishlist.includes(c.id)?'wished':''}" aria-label="${S.wishlist.includes(c.id)?'Remove':'Add'} ${esc(c.name)} ${esc(c.localId)} ${S.wishlist.includes(c.id)?'from':'to'} wishlist">${S.wishlist.includes(c.id)?'♥':'♡'}</button></div></div></article>`;}).join('')||'<p class="muted">No cards match these filters.</p>';$('#load-more').innerHTML=found.length>pageSize?`<button data-action="more">Show 36 more cards</button>`:'';$('#content').onerror=e=>{if(e.target.tagName==='IMG'){e.target.replaceWith(Object.assign(document.createElement('div'),{className:'image-placeholder',textContent:'Artwork unavailable'}));}};}
function exportMissing(){const s=activeSet, mode=S.tracked[s.id]?.mode||'unique';const rows=[['Set','Number','Card','Missing print']];for(const c of s.cards){if(mode==='variants'){for(const v of variants(c))if(!qty(c.id,v))rows.push([c.set.name,c.localId,c.name,names[v]]);}else if(!qty(c.id))rows.push([c.set.name,c.localId,c.name,'Any print']);}const csv=rows.map(r=>r.map(x=>'"'+String(x).replaceAll('"','""')+'"').join(',')).join('\r\n');const u=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download=s.id+'-missing.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);notify((rows.length-1)+' missing entries exported.');}
function selection(){$('#selection-bar').hidden=!selected.size;$('#selected-count').textContent=`${selected.size} card${selected.size===1?'':'s'} selected`;}
function dialog(title,subtitle,body,footer=''){modal.innerHTML=`<div class="dialog-head"><div><h2>${esc(title)}</h2><p>${esc(subtitle)}</p></div><button data-close aria-label="Close dialog">×</button></div><div class="dialog-content">${body}</div>${footer?`<div class="dialog-footer">${footer}</div>`:''}`;if(!modal.open)modal.showModal();}
function explore(){dialog('Find your next set.','Browse the English Pokémon TCG catalogue.',`<input class="set-search" type="search" id="set-search" placeholder="Search sets, e.g. 151 or 30th…" aria-label="Search sets"><button class="primary" data-action="custom" style="margin-bottom:16px">＋ Custom Pokémon set</button><div class="set-list" id="set-list"></div>`);const draw=()=>{const q=$('#set-search').value.toLowerCase();const list=catalogue.filter(s=>!/^([AB]\d|P-A)/.test(s.id)).filter(s=>(s.name+' '+s.id).toLowerCase().includes(q)).reverse();$('#set-list').innerHTML=list.map(s=>`<button class="set-choice" data-set="${esc(s.id)}">${setLogo(s)?`<img src="${esc(setLogo(s))}" alt="" loading="lazy">`:`<span class="set-initial">▧</span>`}<span><b>${esc(s.name)}</b><small>${s.cardCount.total} cards · ${esc(s.id)}${S.tracked[s.id]?' · Tracking':''}</small>${setNote(s)?`<small class="set-description">${setNote(s)}</small>`:''}</span><span class="arrow">↗</span></button>`).join('')||'<p class="muted">No matching sets.</p>';};draw();$('#set-search').addEventListener('input',draw);}
function customSet(){
 dialog('Create a Pokémon master set.','Bring your favourites together across the English catalogue.',`<label class="field">Checklist name<input id="custom-name" value="Ponyta & Rapidash" maxlength="80"></label><label class="field">Pokémon names, separated by commas<input id="custom-pokemon" value="Ponyta, Rapidash" placeholder="Ponyta, Rapidash"></label><label class="field">Checklist scope<select id="custom-mode"><option value="unique">One of each card</option><option value="variants">Standard prints, including reverse holos</option></select></label><p class="price-note">Matches Pokémon card names, including regional forms, ex/V cards and named variants. English catalogue only; special stamps and unlisted releases may be absent. Your owned cards count automatically.</p><div id="custom-preview" aria-live="polite"></div>`,`<button data-close>Cancel</button><button class="primary" id="preview-custom">Find cards across all sets</button><button class="primary" id="create-custom" hidden>Create checklist</button>`);
 let found=null;
 const invalidate=()=>{found=null;$('#create-custom').hidden=true;$('#custom-preview').textContent='';};
 $('#custom-pokemon').oninput=invalidate;
 $('#preview-custom').onclick=async e=>{e.target.disabled=true;$('#create-custom').hidden=true;$('#custom-preview').textContent='Searching the catalogue and loading card details…';try{const pokemon=$('#custom-pokemon').value.split(',').map(x=>x.trim()).filter(Boolean);const data=await api('pokemon-preview',{pokemon});found=pokemon;$('#custom-preview').innerHTML=`<div class="notice"><b>${data.cards.length} cards across ${data.sets} sets</b><p>${data.cards.filter(c=>qty(c.id)).length} already owned.</p></div><div class="custom-matches">${data.cards.map(c=>`<div><b>${esc(c.name)}</b><small>${esc(c.set.name)} · #${esc(c.localId)}</small></div>`).join('')}</div>`;$('#create-custom').hidden=false;}catch(err){$('#custom-preview').textContent=err.message;}finally{e.target.disabled=false;}};
 $('#create-custom').onclick=async e=>{if(!found)return;e.target.disabled=true;try{const before=new Set(Object.keys(S.tracked));await save('custom',{name:$('#custom-name').value,pokemon:found,mode:$('#custom-mode').value});const id=Object.keys(S.tracked).find(id=>!before.has(id));modal.close();await navigate('browse',id);notify('Your Pokémon master set is ready.');}catch(err){notify(err.message);e.target.disabled=false;}};
}
function track(){const s=activeSet,t=S.tracked[s.id],a=progress(s,'unique'),b=progress(s,'variants');dialog('Make this set your next goal.',s.name,`<div class="notice">Tracking a set creates a checklist. It does not mark any cards as owned. Cards already in your vault count automatically.</div><label class="scope-option"><input type="radio" name="scope" value="unique" ${!t||t.mode==='unique'?'checked':''}><span><b>One of each card</b><small>${a.total} numbered cards · ${a.have} already owned. Includes secret cards listed in this set.</small></span></label><label class="scope-option"><input type="radio" name="scope" value="variants" ${t?.mode==='variants'?'checked':''}><span><b>Standard print master set</b><small>${b.total} catalogue-listed prints · ${b.have} already owned. Track regular, holo and reverse holo separately.</small></span></label><p class="price-note">Special stamps, promotional releases and foil-pattern exceptions may not be covered. The standard-print checklist uses TCGdex’s variant flags; it is not an exhaustive every-release master checklist.</p>`,`<button data-close>Cancel</button><button class="primary" id="save-track">${t?'Update checklist':'Start tracking set'}</button>`);$('#save-track').onclick=async e=>{e.target.disabled=true;try{await save('track',{id:s.id,mode:$('input[name=scope]:checked').value});modal.close();render();notify('Set checklist saved. Your owned cards are unchanged.');}catch(err){notify(err.message);e.target.disabled=false;}};}
function review(){const list=[...selected].map(id=>cards.get(id));dialog('Add your selected cards.',`${list.length} cards selected. Choose a print and quantity for each.`,`<div class="batch-defaults"><label class="field">Condition for this batch<select id="batch-condition">${['Near mint','Lightly played','Moderately played','Heavily played','Damaged'].map(n=>`<option>${n}</option>`).join('')}</select></label><label class="field">Quantity for all<input id="batch-quantity" type="number" min="1" max="999" value="1"></label><button id="apply-quantity">Apply</button></div><div class="batch-list">${list.map(c=>`<div class="batch-row" data-row="${esc(c.id)}">${c.image?`<img src="${esc(c.image)}/low.webp" alt="">`:'<span>▧</span>'}<div><b>${esc(c.name)}</b><small>#${esc(c.localId)} · ${qty(c.id)} owned</small></div><select aria-label="Variant for ${esc(c.name)} ${esc(c.localId)}">${variants(c).map(v=>`<option value="${v}">${names[v]}</option>`).join('')}</select><input type="number" min="1" max="999" value="1" aria-label="Quantity for ${esc(c.name)} ${esc(c.localId)}"></div>`).join('')}</div><p class="price-note">Quantities are added to your existing copies. Duplicate cards increase quantity; they never increase set completion. Undo is available after saving.</p>`,`<button data-close>Keep selecting</button><button class="primary" id="save-batch">Add ${list.length} cards to collection</button>`);$('#apply-quantity').onclick=()=>{const q=Number($('#batch-quantity').value);if(!Number.isInteger(q)||q<1||q>999){notify('Choose a whole quantity from 1 to 999.');return;}document.querySelectorAll('[data-row] input').forEach(i=>i.value=q);};$('#save-batch').onclick=async e=>{const rows=[...document.querySelectorAll('[data-row]')].map(r=>({id:r.dataset.row,variant:r.querySelector('select').value,quantity:Number(r.querySelector('input').value),condition:$('#batch-condition').value}));if(rows.some(r=>!Number.isInteger(r.quantity)||r.quantity<1||r.quantity>999)){notify('Every quantity must be a whole number from 1 to 999.');return;}e.target.disabled=true;try{await save('batch',{rows});selected.clear();modal.close();render();notify(`${rows.reduce((n,r)=>n+r.quantity,0)} cards added to your vault.`);}catch(err){notify(err.message);e.target.disabled=false;}};}
function renderMasters(){const entries=Object.entries(S.tracked);if(!entries.length){$('#content').innerHTML=empty('Every complete set starts somewhere.','Pick a set to create its full checklist. Your missing cards and completion progress will live here.','Find a set to master')+'<button class="primary" data-action="custom">＋ Custom Pokémon set</button>';return;}$('#content').innerHTML=`<div class="results-line"><p>Expansion sets and your favourite Pokémon, together.</p><button class="primary" data-action="custom">＋ Custom Pokémon set</button></div><div class="master-grid">${entries.map(([id,t])=>{const s=sets.get(id),p=progress(s,t.mode);return `<article class="master-tile">${s.pokemon?pokemonArt(s):setLogo(s)?`<img class="set-logo" src="${esc(setLogo(s))}" alt="${esc(s.name)}">`:'<div class="kicker">POKÉMON TCG</div>'}<h2>${esc(t.name)}</h2>${setNote(s)?`<small class="set-description">${setNote(s)}</small>`:''}<p>${t.mode==='variants'?'Standard print master set':'One of each numbered card'}</p><div class="results-line"><span>${p.have} / ${p.total} owned</span><b>${p.percent}%</b></div><div class="progress"><i style="width:${p.percent}%"></i></div><small>${p.missing} ${t.mode==='variants'?'prints':'cards'} left to find</small><button data-set="${esc(id)}">Open checklist →</button><button class="remove-set" data-untrack="${esc(id)}">Remove set</button></article>`;}).join('')}</div>`;}
function renderStats(){const owned=Object.values(S.owned);if(!owned.length){$('#content').innerHTML=empty('Your story is just getting started.','Add your first cards to see a breakdown of your collection.');return;}let value=0,priced=0;const bySet={};for(const r of owned){const c=cards.get(r.id),p=price(c,r.variant);if(p!==null){value+=p*r.quantity;priced+=r.quantity;}const name=c.set.name;bySet[name]=(bySet[name]||0)+r.quantity;}const total=owned.reduce((n,r)=>n+r.quantity,0);$('#content').innerHTML=`<div class="stats-panel"><div class="kicker">MARKET REFERENCE · USD</div><h2>${money(value)}</h2><p class="price-note">TCGplayer market estimates via TCGdex, from cached catalogue snapshots. ${priced} of ${total} copies have matched prices. Prices are not adjusted for your card condition; unpriced copies are excluded. This is a reference total, not a sale quote.</p></div><div class="stats-panel" style="margin-top:20px"><h2>By set</h2>${Object.entries(bySet).sort((a,b)=>b[1]-a[1]).map(([name,n])=>`<div class="stats-row"><div><span>${esc(name)}</span><small>${n} cards · ${Math.round(n/total*100)}%</small></div><div class="progress"><i style="width:${n/total*100}%"></i></div></div>`).join('')}</div>`;}
async function detail(id){try{const c=await getCard(id),h=holdings(id);dialog(c.name,`${c.set.name} · #${c.localId} · ${c.rarity||'Rarity unavailable'}`,`<div class="detail-layout">${image(c)}<div><div class="detail-rarity">${rarityBadge(c)}<span>${esc(c.rarity||'Rarity unavailable')}</span></div><div class="kicker">IN YOUR VAULT</div><h2>${qty(id)} copies</h2>${h.map(r=>`<div class="holding"><span>${names[r.variant]}<small> · ${esc(r.condition)}</small></span><button data-adjust="-1" data-key="${esc(r.id+'|'+r.variant+'|'+r.condition)}" aria-label="Remove one ${names[r.variant]}">−</button><b>${r.quantity}</b><button data-adjust="1" data-key="${esc(r.id+'|'+r.variant+'|'+r.condition)}" aria-label="Add one ${names[r.variant]}">+</button></div>`).join('')||'<p>No copies owned yet.</p>'}<p>Available prints: ${variants(c).map(v=>names[v]).join(', ')}.</p><button class="primary" id="detail-add">Select to add →</button><p class="price-note">${c.pricing?.tcgplayer?.updated?'Price snapshot: '+esc(c.pricing.tcgplayer.updated.slice(0,10))+' · TCGplayer via TCGdex.':'No TCGplayer price snapshot available.'}<br>Standard print availability is based on catalogue flags.</p></div></div>`);$('#detail-add').onclick=()=>{selected.add(id);modal.close();render();review();};document.querySelectorAll('[data-adjust]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const r=S.owned[b.dataset.key];await save('batch',{operation:'set',rows:[{...r,quantity:r.quantity+Number(b.dataset.adjust)}]});render();await detail(id);}catch(e){notify(e.message);b.disabled=false;}});}catch(e){notify(e.message);}}
document.addEventListener('click',async e=>{const close=e.target.closest('[data-close]');if(close){modal.close();return;}const b=e.target.closest('button');if(b?.dataset.nav){navigate(b.dataset.nav);return;}if(b?.dataset.untrack){const id=b.dataset.untrack;dialog('Remove this checklist?',S.tracked[id].name,'<p>Your owned cards and wishlist will stay in your collection. Only this set’s checklist will be removed. You can Undo this change.</p>','<button data-close>Keep set</button><button class="primary" id="confirm-untrack">Remove checklist</button>');$('#confirm-untrack').onclick=async ev=>{ev.target.disabled=true;try{await save('untrack',{id});modal.close();await navigate('master');notify('Checklist removed. Owned cards kept. Undo is available.');}catch(err){notify(err.message);ev.target.disabled=false;}};return;}const se=e.target.closest('[data-set]');if(se){modal.close();navigate('browse',se.dataset.set);return;}if(b?.dataset.filter){filter=b.dataset.filter;pageSize=36;renderCards();return;}const de=e.target.closest('[data-detail]');if(de){detail(de.dataset.detail);return;}if(b?.dataset.wish){b.disabled=true;try{await save('wish',{id:b.dataset.wish});render();notify('Wishlist updated.');}catch(err){notify(err.message);b.disabled=false;}return;}switch(b?.dataset.action){case 'custom':customSet();break;case 'export-missing':exportMissing();break;case 'explore':explore();break;case 'track':track();break;case 'select-visible':displayed.forEach(c=>selected.add(c.id));renderCards();selection();break;case 'more':pageSize+=36;renderCards();break;case 'retry':navigate(view,activeSet?.id);break;}});
document.addEventListener('change',e=>{if(e.target.dataset.select){const id=e.target.dataset.select;if(e.target.checked)selected.add(id);else selected.delete(id);e.target.closest('.card').classList.toggle('selected',e.target.checked);selection();}});
$('#browse-sets').onclick=explore;$('#review').onclick=review;$('#clear-selection').onclick=()=>{selected.clear();render();};$('#undo').onclick=async()=>{try{await save('undo',{});await navigate(view,activeSet?.id);notify('Last collection change undone.');}catch(e){notify(e.message);}};
$('#backup').onclick=async()=>{try{const d=await api('export');const url=URL.createObjectURL(new Blob([JSON.stringify(d,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='tcg-vault-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Collection backup exported.');}catch(e){notify(e.message);}};
window.addEventListener('hashchange',()=>{if(location.hash==='#browse')navigate('browse');});
async function init(){try{const d=await api('state');token=d.token;delete d.token;S=d;catalogue=await api('sets');await navigate('browse');}catch(e){failure(e);}}
init();

let syncBusy=false;async function syncVault(){if(syncBusy||modal.open||selected.size||document.hidden)return;syncBusy=true;try{const d=await api('state');if(d.revision!==S.revision){token=d.token;delete d.token;S=d;sets.clear();await navigate(view,activeSet?.id);notify('Shared collection updated.');}}catch{}finally{syncBusy=false;}}setInterval(syncVault,15000);window.addEventListener('focus',syncVault);
if(document.modelContext?.registerTool)document.modelContext.registerTool({name:'read_collection_summary',description:'Read counts from the shared Pokémon collection.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({ownedCopies:Object.values(S.owned).reduce((n,x)=>n+x.quantity,0),checklists:Object.values(S.tracked).map(x=>x.name),wishlist:S.wishlist.length})});
